create or replace function apply_audit_triggers() returns void language plpgsql security invoker set search_path=public as $$declare r record;begin for r in select tablename from pg_tables where schemaname='public' and tablename in ('customers','shippers','suppliers','ports','port_alias_map','products','raw_materials','packing_items','sales_plans','sales_plan_lines','sales_updates','production_updates','box_interchanges','loose_unit_adjustments','purchases','stock_transfers','stock_audits','import_batches','shipping_staging_rows','shipping_master','machine_production_queue') loop execute format('create trigger audit_%I after insert or update or delete on %I for each row execute function audit_row()',r.tablename,r.tablename); end loop;end $$;
select apply_audit_triggers(); drop function apply_audit_triggers();

